samples = [
    float(x.strip())
    for x in text.replace("\r", "").replace("\n", "").split(",")
    if x.strip()
]

with open("monk.raw", "wb") as f:
    for sample in samples:
        # Your monk was producing values around +/-2.5
        sample = max(-1.0, min(1.0, sample * 0.25))
        pcm = int(sample * 32767)
        f.write(struct.pack("<h", pcm))

print(f"Wrote {len(samples)} samples")